#include "mex.h"
#include <licensebox_json.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
typedef struct state{uint64_t id;lb_client*p;mxArray*callbacks;int busy,failed;struct state*next;}state;
static state*head;static uint64_t nextid=1;
static char* text(const mxArray*a){if(!mxIsChar(a))mexErrMsgIdAndTxt("licensebox:invalid_argument","Expected a character vector");const mxChar*chars=mxGetChars(a);size_t n=mxGetNumberOfElements(a);for(size_t i=0;i<n;i++)if(chars[i]==0)mexErrMsgIdAndTxt("licensebox:invalid_argument","NUL in argument");char*s=mxArrayToString(a);if(!s)mexErrMsgIdAndTxt("licensebox:invalid_argument","Cannot encode UTF-8");return s;}
static char* raw_text(const mxArray*a){if(!mxIsChar(a))mexErrMsgIdAndTxt("licensebox:identity_unavailable","Expected native identifier text");const mxChar*chars=mxGetChars(a);size_t n=mxGetNumberOfElements(a);while(n&&chars[n-1]==0)n--;for(size_t i=0;i<n;i++)if(chars[i]==0)mexErrMsgIdAndTxt("licensebox:identity_unavailable","Embedded NUL in native identifier");char*s=mxArrayToString(a);if(!s)mexErrMsgIdAndTxt("licensebox:identity_unavailable","Cannot encode native identifier");return s;}
static mxArray* invoke(state*s,int n,int count,mxArray**args){const mxArray*fn=mxGetCell(s->callbacks,n);if(mxIsEmpty(fn))return NULL;mxArray*in[3]={(mxArray*)fn,NULL,NULL},*out=NULL;for(int i=0;i<count;i++)in[i+1]=args[i];mxArray*error=mexCallMATLABWithTrap(1,&out,count+1,in,"feval");if(error){s->failed=1;mxDestroyArray(error);if(out)mxDestroyArray(out);return NULL;}return out;}
static void signin(void*x,const char*u,const char*c){state*s=x;mxArray*a[2]={mxCreateString(u),mxCreateString(c)};mxArray*v=invoke(s,0,2,a);if(v)mxDestroyArray(v);mxDestroyArray(a[0]);mxDestroyArray(a[1]);}
static double clock_cb(void*x){state*s=x;mxArray*v=invoke(s,1,0,NULL);double n=v&&mxIsDouble(v)&&mxGetNumberOfElements(v)==1?mxGetScalar(v):NAN;if(!isfinite(n))s->failed=1;if(v)mxDestroyArray(v);return isfinite(n)?n:0;}
static int binding(void*x,char*out,size_t cap){state*s=x;mxArray*v=invoke(s,2,0,NULL);int ok=v&&mxIsChar(v);if(ok){char*t=mxArrayToString(v);ok=t&&strlen(t)<cap;if(ok)memcpy(out,t,strlen(t)+1);if(t)mxFree(t);}if(!ok)s->failed=1;if(v)mxDestroyArray(v);return ok?0:1;}
static int cancelled(void*x){state*s=x;if(s->failed)return 1;const mxArray*fn=mxGetCell(s->callbacks,3);if(mxIsEmpty(fn))return 0;mxArray*v=invoke(s,3,0,NULL);int ok=v&&(mxIsLogical(v)||mxIsDouble(v))&&mxGetNumberOfElements(v)==1;int n=ok?mxGetScalar(v)!=0:1;if(!ok)s->failed=1;if(v)mxDestroyArray(v);return s->failed||n;}
static void clean(void){while(head){state*s=head;head=s->next;lb_client_destroy(s->p);mxDestroyArray(s->callbacks);mxFree(s);}}
static state* get(const mxArray*a){if(!mxIsUint64(a)||mxGetNumberOfElements(a)!=1)mexErrMsgIdAndTxt("licensebox:invalid_argument","Invalid client handle");uint64_t id=*(uint64_t*)mxGetData(a);for(state*s=head;s;s=s->next)if(s->id==id){if(s->busy)mexErrMsgIdAndTxt("licensebox:invalid_argument","Callbacks must not reenter the client");return s;}mexErrMsgIdAndTxt("licensebox:closed","Client is closed");return NULL;}
static void result(lb_result rc,char*out,state*s,mxArray**answer){if(s&&s->failed){lb_free(out);s->failed=0;mexErrMsgIdAndTxt("licensebox:callback","Callback failed");}if(rc){lb_free(out);const char*code=s?lb_error_code(s->p):lb_result_code(rc);if(!code||!strcmp(code,"ok")||rc==LB_INVALID_ARGUMENT)code=lb_result_code(rc);char id[128];snprintf(id,sizeof(id),"licensebox:%s",code);mexErrMsgIdAndTxt(id,"Licensebox operation failed: %s",code);}*answer=mxCreateString(out?out:"null");lb_free(out);}
void mexFunction(int nlhs,mxArray**plhs,int nrhs,const mxArray**prhs){if(nlhs!=1||nrhs<1)mexErrMsgIdAndTxt("licensebox:invalid_argument","One output is required");char*op=text(prhs[0]);
if(!strcmp(op,"create")){if(nrhs!=3||!mxIsCell(prhs[2])||mxGetNumberOfElements(prhs[2])!=4)mexErrMsgIdAndTxt("licensebox:invalid_argument","Expected options and four callbacks");state*s=mxCalloc(1,sizeof(*s));s->callbacks=mxDuplicateArray(prhs[2]);mexMakeArrayPersistent(s->callbacks);char*opts=text(prhs[1]);lb_callbacks cb={s,mxIsEmpty(mxGetCell(s->callbacks,0))?NULL:signin,mxIsEmpty(mxGetCell(s->callbacks,1))?NULL:clock_cb,mxIsEmpty(mxGetCell(s->callbacks,2))?NULL:binding,cancelled};lb_result rc=lb_client_create_json(opts,&cb,&s->p);mxFree(opts);if(rc||s->failed){lb_client_destroy(s->p);mxDestroyArray(s->callbacks);mxFree(s);mxFree(op);char id[128];snprintf(id,sizeof(id),"licensebox:%s",lb_result_code(rc?rc:LB_CANCELLED));mexErrMsgIdAndTxt(id,"Client creation failed");}mexMakeMemoryPersistent(s);s->id=nextid++;s->next=head;head=s;plhs[0]=mxCreateNumericMatrix(1,1,mxUINT64_CLASS,mxREAL);*(uint64_t*)mxGetData(plhs[0])=s->id;mexLock();mexAtExit(clean);
}else if(!strcmp(op,"close")){state*s=get(prhs[1]);state**p=&head;while(*p!=s)p=&(*p)->next;*p=s->next;lb_client_destroy(s->p);mxDestroyArray(s->callbacks);mxFree(s);mexUnlock();plhs[0]=mxCreateDoubleMatrix(0,0,mxREAL);
}else if(!strcmp(op,"call")){if(nrhs!=4)mexErrMsgIdAndTxt("licensebox:invalid_argument","Expected handle, operation, arguments");state*s=get(prhs[1]);char*kind=text(prhs[2]),*args=text(prhs[3]),*out=NULL;s->busy=1;lb_result rc=lb_client_call_json(s->p,kind,args,&out);s->busy=0;mxFree(kind);mxFree(args);mxFree(op);result(rc,out,s,&plhs[0]);return;
}else if(!strcmp(op,"derive")||!strcmp(op,"native")){char*product=text(prhs[1]);char out[128];lb_result rc;if(!strcmp(op,"derive")){char*source=text(prhs[2]),*raw=raw_text(prhs[3]);rc=lb_derive_binding(product,source,raw,out,sizeof(out));mxFree(source);mxFree(raw);}else rc=lb_native_binding(product,out,sizeof(out));mxFree(product);if(rc){mxFree(op);result(rc,NULL,NULL,&plhs[0]);return;}plhs[0]=mxCreateString(out);
}else if(!strcmp(op,"verify")){char*t=text(prhs[1]),*p=text(prhs[2]),*k=text(prhs[3]),*out=NULL;lb_result rc=lb_verify_lease_json(t,p,k,mxGetScalar(prhs[4]),&out);mxFree(t);mxFree(p);mxFree(k);mxFree(op);result(rc,out,NULL,&plhs[0]);return;
}else{mxFree(op);mexErrMsgIdAndTxt("licensebox:invalid_argument","Unknown bridge operation");}mxFree(op);}
